// FieldShift appearance settings
const themeModes = ['light', 'mixed', 'dark'];
let currentTheme = 'mixed';

try {
  const savedTheme = localStorage.getItem('fieldshift_theme');
  if (themeModes.includes(savedTheme)) {
    currentTheme = savedTheme;
  }
} catch {}

if (document.documentElement?.dataset) {
  document.documentElement.dataset.theme = currentTheme;
}

function setFieldShiftTheme(mode) {
  if (!themeModes.includes(mode)) return;
  currentTheme = mode;
  document.documentElement.dataset.theme = mode;

  try {
    localStorage.setItem('fieldshift_theme', mode);
  } catch {}

  const button = document.querySelector('#themeToggle');
  if (button) {
    button.textContent =
      mode === 'dark' ? '🌙 Dark' :
      mode === 'mixed' ? '🌗 Mixed' :
      '☀️ Light';
  }
}

document.addEventListener('click', event => {
  if (!event.target.closest('#themeToggle')) return;

  const index = themeModes.indexOf(currentTheme);
  const next = themeModes[(index + 1) % themeModes.length];

  setFieldShiftTheme(next);
});

