const rotations=[{name:'Your current approach',seq:'Maize → Maize → Beans',benefit:'Baseline to compare future choices',soil:49,water:57,diversity:43,risk:'Repeated maize may create soil and pest-management concerns.'},{name:'Legume rotation',seq:'Maize → Beans → Sweet potato',benefit:'Diversifies crop families and may interrupt some pest cycles.',soil:77,water:70,diversity:85,risk:'Requires locally suitable growing seasons and seed availability.'},{name:'Mixed diversification',seq:'Maize → Soybean → Beans',benefit:'Includes legumes that may fix nitrogen under suitable conditions.',soil:71,water:62,diversity:65,risk:'Success depends on soils, inoculation, pest pressure and local demand.'}];
export function scoreRotation(r,p){const w=p==='Water conservation'?[.2,.6,.2]:p==='Crop diversity'?[.2,.2,.6]:[.55,.25,.2];return Math.round(r.soil*w[0]+r.water*w[1]+r.diversity*w[2])}
function rotation(){let choice=state.profile.priority;layout(`${contextBanner()}<div class="grid two" style="grid-template-columns:300px minmax(0,1fr)"><div class="card"><h3 style="margin-top:0">Your planning context</h3><div class="field"><label class="label">Current crops</label><input id="rotCrops" class="input" value="${escapeHTML(state.profile.crops)}" readonly></div><div class="field"><label class="label">Farmer's top priority</label><select id="rotationPriority" class="input">${['Soil health','Water conservation','Crop diversity'].map(x=>`<option ${choice===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="notice">Scores are illustrative teaching examples, not model predictions. Local crop calendars, soils, varieties and agronomists must validate every option.</div></div><div><div class="section-head" style="margin-top:0"><h3>Compare three scenarios</h3><span class="badge-demo">Demonstration algorithm</span></div>${state.savedRotations?.length?`<p class="muted">✓ ${state.savedRotations.length} rotation plans saved privately in Supabase</p>`:''}${rotations.map((r,i)=>`<div class="rotation ${i===1?'best':''}"><div class="row"><b>${escapeHTML(r.name)}</b><span class="chip">${scoreRotation(r,choice)} / 100 · demo</span></div><div class="rot-seq">${escapeHTML(r.seq)}</div><p class="muted">${escapeHTML(r.benefit)}</p><div class="progress"><div style="width:${scoreRotation(r,choice)}%"></div></div><p class="muted"><b>Review locally:</b> ${escapeHTML(r.risk)}</p><div class="row rotation-actions"><button class="textbtn ask-rotation" data-rot="${i}">Discuss with AI →</button><button class="btn small secondary" data-save-rotation="${i}" ${state.auth&&state.farms.length?'':'disabled'}>Save to my farm</button></div></div>`).join('')}</div></div><p class="footer">Illustrative weights: soil health 55% / water 25% / diversity 20%, adjustable via priority. No yield prediction or guaranteed outcome.</p>`);if(innerWidth<900)$('.main .grid.two').style.gridTemplateColumns='1fr'}
function climateMini(){return `<div style="margin:15px 0;padding:12px;background:#f5faf5;border-radius:12px"><div class="row"><b style="font-size:12px">Climate observations</b><span class="badge-demo">${state.climateStatus==='live'?'NASA POWER':'Data not loaded'}</span></div><p class="muted" style="margin:8px 0">${state.climateStatus==='live'?'Retrieved historical climate series. View dates on Climate Intelligence.':'Visit Climate Intelligence to request NASA POWER data for this district.'}</p></div>`}
function plot(data,key,label){const points=data.map((d,i)=>[12+i*(600/Math.max(data.length-1,1)),170-Math.max(0,Math.min(150,((d[key]-Math.min(...data.map(v=>v[key])))/(Math.max(...data.map(v=>v[key]))-Math.min(...data.map(v=>v[key]))||1))*145))]);return `<svg class="chart" viewBox="0 0 630 210" role="img" aria-label="${escapeHTML(label)} trend chart">${[35,85,135,175].map(y=>`<line x1="8" x2="620" y1="${y}" y2="${y}" stroke="#e5ede6"/>`).join('')}<polyline fill="none" stroke="#288457" stroke-width="4" stroke-linejoin="round" points="${points.map(p=>p.join(',')).join(' ')}"/>${points.filter((_,i)=>i%Math.max(1,Math.floor(points.length/12))===0).map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#288457"/>`).join('')}</svg>`}
function climate(){const loc=districts[state.profile.district]||districts.Musanze;const d=state.climate;layout(`${contextBanner()}<div class="card"><div class="row" style="flex-wrap:wrap"><div><h3 style="margin:0 0 7px">NASA POWER historical climate explorer</h3><p class="muted">Approximate district-center coordinates: ${loc.lat}, ${loc.lon}</p></div><button id="loadClimate" class="btn">${state.climateStatus==='loading'?'Loading...':'↻ Load NASA observations'}</button></div><p class="notice">The NASA POWER API provides gridded historical estimates, not real-time field sensor measurements. For irrigation or landslide safety decisions, verify conditions locally and consult official alerts.</p>${state.climateStatus==='error'?`<div class="notice warn" role="alert">NASA request failed: ${escapeHTML(state.climateError||'Unavailable')}. No simulated observations are shown. Try again later.</div>`:''}${d?`<div class="grid two" style="margin-top:18px"><div><h3>Temperature (°C)</h3>${plot(d,'temp','Daily mean temperature')}</div><div><h3>Rainfall (mm/day)</h3>${plot(d,'rain','Daily precipitation')}</div></div><div class="row" style="flex-wrap:wrap"><span class="chip">${state.climateStatus==='live'?'Verified NASA POWER response':'Illustrative fallback data'}</span><span class="muted">${escapeHTML(d.length)} daily observations · ${escapeHTML(d[0].date)} to ${escapeHTML(d[d.length-1].date)}</span></div>`:'<div class="empty">☁ Select “Load NASA observations” to retrieve historical rainfall and temperature.</div>'}</div><div class="section-head"><h3>What these indicators tell us</h3></div><div class="grid three"><div class="card"><h3>🌧 Rainfall trends</h3><p class="muted">Historical precipitation can inform seasonal water considerations, but not precise future rainfall.</p></div><div class="card"><h3>☀ Heat stress</h3><p class="muted">Temperature patterns help identify the need to evaluate heat-sensitive crop choices.</p></div><div class="card"><h3>🌱 Soil and vegetation</h3><p class="muted">Additional satellite and local soil data must be integrated before site-specific soil claims.</p></div></div>`)}
async function fetchClimate(){if(state.country!=='Rwanda'){state.climateStatus='error';state.climateError='District climate data is currently configured for Rwanda only. Select Rwanda for the current district climate module or consult NASA POWER directly.';climate();return;}state.climateStatus='loading';climate();const {lat,lon}=districts[state.profile.district]||districts.Musanze;const now=new Date();const end=new Date(now.getTime()-7*86400000),start=new Date(end.getTime()-48*86400000);const f=d=>d.toISOString().slice(0,10).replace(/-/g,'');const nasaQuery=`parameters=T2M,PRECTOTCORR&community=AG&longitude=${lon}&latitude=${lat}&start=${f(start)}&end=${f(end)}&format=JSON&time-standard=UTC`;const url=`/api/nasa-power?${nasaQuery}`;try{let res;try{res=await fetch(url,{signal:AbortSignal.timeout(16000)});if(!res.ok && res.status===404)throw Error("Proxy unavailable")}catch(proxyErr){res=await fetch(`https://power.larc.nasa.gov/api/temporal/daily/point?${nasaQuery}`,{signal:AbortSignal.timeout(16000)})}if(!res.ok)throw Error('NASA POWER HTTP '+res.status);const json=await res.json();const p=json.properties.parameter;const temp=p.T2M,rain=p.PRECTOTCORR;const arr=Object.keys(temp).map(date=>({date,temp:Number(temp[date]),rain:Number(rain[date])})).filter(x=>x.temp>-900&&x.rain>-900&&Number.isFinite(x.temp)&&Number.isFinite(x.rain));if(arr.length<4)throw Error('No usable observations');state.climate=arr;state.climateStatus='live'}catch(err){state.climateStatus='error';state.climate=null;state.climateError=err.message;console.warn('NASA request unavailable, no simulated observations presented',err)}climate()}

async function loadMarketInquiries(){
 if(!state.supabase||!state.auth){state.marketInquiries=[];return;}
 const ids=state.marketCloud.filter(x=>x.user_id===state.auth.id).map(x=>x.id);
 if(!ids.length){state.marketInquiries=[];return;}
 const {data,error}=await state.supabase.from('market_inquiries').select('id,listing_id,sender_id,message,created_at').in('listing_id',ids).order('created_at',{ascending:false}).limit(50);
 state.marketInquiries=error?[]:(data||[]);
 if(error)state.marketInboxError=error.message;
}

