export function answerQuestion(input){const q=input.toLowerCase();if(/what('s| is)? crop rotation|explain crop rotation|crop rotation about/i.test(q))return 'Crop rotation means growing different crops in the same field across seasons. For example: maize → beans → sweet potatoes. This can diversify soil use and help manage some pests, but the best sequence depends on rainfall, soil, crop disease history and local planting calendars. Open Nova Planner to compare options.';if(/beans|maize|rotation|crop|ibihingwa|ibigori/i.test(q))return 'Compare your current rotation with at least two different crop sequences. A legume such as beans can add diversity, but nitrogen benefits depend on soil biology and management. Check local crop calendars, disease history, seed availability, water conditions and expert advice.';if(/rain|water|drought|imvura|amazi/i.test(q))return 'Open Climate Intelligence to view historical NASA POWER rainfall estimates. Past rainfall does not guarantee future conditions. Compare the observation dates and ask nearby farmers about actual water availability.';if(/soil|erosion|landslide|ubutaka/i.test(q))return 'Maintaining cover on sloping fields may help reduce erosion. Specific techniques depend on slope, soil and land management; for dangerous landslide or flood situations follow authorized local warnings and expert guidance.';if(/market|sell|buyer|isoko/i.test(q))return 'Use Local Nova Market to explore demonstration listings by district. Verify buyer identity, prices, transport and payment arrangements before making a real transaction.';return 'I can help explore crop rotation, rainfall, soil cover and nearby farmer discussions. Tell me your current crops and your main goal—soil health, water conservation or diversification—and compare the rotation options with your local agriculture advisor.'}
