// Live Supabase farming records. Demo content is never written to a user's account.
async function loadFarmData(){
 if(!state.supabase||!state.auth)return;
 const uid=state.auth.id;
 const [farms,seasons,plans]=await Promise.all([
  state.supabase.from('farms').select('id,farm_name,district,sector,area_hectares,soil_type,irrigation_type,water_availability,created_at').eq('user_id',uid).order('created_at',{ascending:false}),
  state.supabase.from('crop_seasons').select('id,farm_id,crop_name,season_label,planting_date,area_hectares,field_notes').eq('user_id',uid).order('created_at',{ascending:false}),
  state.supabase.from('rotation_plans').select('id,farm_id,plan_name,planned_crops,farmer_priority,created_at').eq('user_id',uid).order('created_at',{ascending:false})
 ]);
 state.farms=farms.data||[];state.seasons=seasons.data||[];state.savedRotations=plans.data||[];
 state.farmError=[farms,seasons,plans].find(r=>r.error)?.error?.message||'';
}
