document.addEventListener('submit',async e=>{const form=e.target;if(!['postForm','profileForm','marketForm','chatForm','searchForm','greenhouseForm','storyForm','farmForm','seasonForm'].includes(form.id)&&!form.classList.contains('reply-form'))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));if(form.id==='storyForm'){await submitStory(form);return}if(form.id==='farmForm'){await saveFarm(data);return}if(form.id==='seasonForm'){await saveSeason(data);return}if(form.id==='searchForm'){state.searchTerm=(data.term||'').trim().slice(0,80);state.page='community';render();return}if(form.id==='greenhouseForm'){state.greenhouse={crop:data.crop,season:data.season,water:data.water};storage.set('greenhouse',state.greenhouse);greenhouse();return}if(form.id==='postForm'){if(!data.body.trim())return;await addPost({id:uid(),name:state.profile.name,district:state.profile.district,sector:state.profile.sector,topic:data.topic,body:data.body.trim(),date:'Just now',likes:0,comments:[]});community()}else if(form.classList.contains('reply-form')){if(!data.reply.trim())return;await addReply(form.dataset.id,data.reply.trim());render();$('#comments-'+form.dataset.id)?.classList.remove('hidden')}else if(form.id==='profileForm'){state.profile={name:data.name.trim(),district:data.district,sector:data.sector,crops:data.crops.trim()||'Not entered',priority:data.priority};saveState();render();$('#profileSaved').textContent='Saved ✓';if(state.supabase&&state.auth){const {error}=await state.supabase.from('farmer_profiles').upsert({user_id:state.auth.id,display_name:state.profile.name,district:state.profile.district,sector:state.profile.sector,crops:state.profile.crops,priority:state.profile.priority});if(error)alert('Profile sync failed: '+error.message);else await recordActivity('profile_update','Updated private farm profile')}else if(state.firestore&&state.auth)try{await state.fb.setDoc(state.fb.doc(state.firestore,'profiles',state.auth.uid),state.profile)}catch(err){console.error(err)}}else if(form.id==='marketForm'){await publishMarketListing(data)}else if(form.id==='chatForm'){state.chat.push({role:'user',text:data.query});state.chat.push({role:'bot',text:'Preparing your explanation…'});advisor();const msg=await askNvidia(data.query);state.chat[state.chat.length-1]={role:'bot',text:msg};advisor()}});
async function initFirebase(){
  try {
    // Firebase web configuration is PUBLIC app identification, not a server secret.
    // Vite injects these values from .env.local or Vercel project environment variables.
    const {firebaseConfig} = await import('./firebase-config.js');
    if(!firebaseConfig.apiKey || !firebaseConfig.authDomain || !firebaseConfig.projectId || !firebaseConfig.appId){
      state.authError='Firebase environment variables are missing. Ask the team administrator to configure Google authentication.';
      render();return;
    }
    const appMod=await import('https://www.gstatic.com/firebasejs/11.6.0/firebase-app.js');
    const authMod=await import('https://www.gstatic.com/firebasejs/11.6.0/firebase-auth.js');
    const dbMod=await import('https://www.gstatic.com/firebasejs/11.6.0/firebase-firestore.js');
    const app=appMod.initializeApp(firebaseConfig);
    const auth=authMod.getAuth(app);
    const db=dbMod.getFirestore(app);
    state.fb={...authMod,...dbMod,auth};state.firestore=db;state.authReady=true;state.authError='';
    authMod.onAuthStateChanged(auth,async user=>{
      state.auth=user;
      if(user){
        state.profile.name=user.displayName||state.profile.name;
        try{
          const snap=await dbMod.getDoc(dbMod.doc(db,'profiles',user.uid));
          if(snap.exists())state.profile={...state.profile,...snap.data()};
          const q=dbMod.query(dbMod.collection(db,'posts'),dbMod.orderBy('createdAt','desc'),dbMod.limit(50));
          const data=await dbMod.getDocs(q);
          const remote=data.docs.map(d=>({id:'cloud-'+d.id,remoteId:d.id,...d.data(),likes:0,date:'Community post',comments:[]}));
          state.posts=[...remote,...storage.get('posts',seedPosts).filter(p=>!p.remoteId)];
        }catch(err){state.authError='Account connected, but community database could not be loaded: '+err.message;console.warn(err)}
      }
      render();
    },err=>{state.authError=err.message;render()});
    render();
  }catch(err){state.authError='Firebase initialization failed: '+err.message;console.error(err);render()}
}
render();initSupabase().then(ok=>{if(!ok)initFirebase()});


// NEW MODULES: Scientific what-if scenarios are illustrative and must not be interpreted as forecasts.
function simulation(){const rain=Number(storage.get('scenarioRain',0));const heat=Number(storage.get('scenarioHeat',0));const cases=[{name:'Drier season',rain:-25,heat:2.5,icon:'☀️'},{name:'Balanced reference',rain:0,heat:0,icon:'🌤️'},{name:'Wetter season',rain:30,heat:0.7,icon:'🌧️'}];layout(`${contextBanner()}<section class="card"><h3>Climate simulation laboratory</h3><p class="muted">Adjust hypothetical changes to rainfall and air temperature to discuss how plans may respond. These are NOT NASA forecasts or yield predictions.</p><div class="grid two"><div><label class="label" for="simRain">Rainfall scenario: <strong>${rain>0?'+':''}${rain}%</strong></label><input id="simRain" type="range" min="-50" max="50" step="5" value="${rain}" style="width:100%"/><label class="label" for="simHeat" style="margin-top:22px">Temperature scenario: <strong>+${heat}°C</strong></label><input id="simHeat" type="range" min="0" max="4" step="0.5" value="${heat}" style="width:100%"/><div class="notice" style="margin-top:20px">${rain<-15?'Less rain may increase irrigation needs.':rain>20?'Heavy rain may raise erosion and drainage concerns.':'Near-baseline rainfall assumed.'} ${heat>2?'Greater heat may raise crop water demand.':'Review crop calendars and local observations.'}</div></div><div class="card" style="background:#f7faf6"><h3>Scenario considerations</h3><div class="list-line">Soil cover <b style="float:right">${rain>20?'Higher priority':'Important'}</b></div><div class="list-line">Water storage <b style="float:right">${rain<0?'Higher priority':'Review'}</b></div><div class="list-line">Heat adaptation <b style="float:right">${heat>=2?'Higher priority':'Review'}</b></div><p class="muted">Risk descriptions are qualitative prompts, not quantified outputs of a calibrated model.</p></div></div></section><div class="grid three" style="margin-top:16px">${cases.map(c=>`<div class="card"><div style="font-size:36px">${c.icon}</div><h3>${c.name}</h3><div class="list-line">Rainfall ${c.rain>0?'+':''}${c.rain}%</div><div class="list-line">Temperature +${c.heat}°C</div><p class="muted">Illustrative comparison scenario.</p></div>`).join('')}</div>`);['simRain','simHeat'].forEach(id=>{const el=$('#'+id);if(el)el.oninput=()=>{storage.set(id==='simRain'?'scenarioRain':'scenarioHeat',Number(el.value));simulation()}})}
function greenhouse(){const saved=storage.get('greenhouse',{crop:'Tomatoes',season:'Season A',water:'Limited'});const isTomato=(saved.crop==='Tomatoes');layout(`${contextBanner()}<div class="grid two"><section class="card"><h3>Greenhouse season planner</h3><p class="muted">Explore growing considerations for a protected-crop system. This is planning support, not precise planting-date or fertilizer advice.</p><form id="greenhouseForm"><div class="field"><label class="label">Crop</label><select class="input" name="crop">${['Tomatoes','Peppers','Lettuce','Cucumber'].map(x=>`<option ${x===saved.crop?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label class="label">Rwanda growing season</label><select class="input" name="season">${['Season A','Season B','Season C'].map(x=>`<option ${x===saved.season?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label class="label">Water supply</label><select class="input" name="water">${['Limited','Reliable','Rainwater collection'].map(x=>`<option ${x===saved.water?'selected':''}>${x}</option>`).join('')}</select></div><button class="btn">Compare conditions</button></form></section><section class="card"><h3>Planning guidance</h3><div class="list-line">🌱 ${escapeHTML(saved.crop)} · ${escapeHTML(saved.season)}</div><div class="list-line">💧 Water: ${escapeHTML(saved.water)}</div><p>${isTomato?'Tomatoes generally need careful ventilation, irrigation, and disease monitoring.':'Assess temperature, ventilation, irrigation and crop-specific protection needs.'}</p><p class="muted">Season definitions and crop suitability vary by elevation and local climate. Validate with district agronomists and current Rwandan guidance before planting.</p><button class="btn secondary" data-page="climate">Inspect NASA climate history ↗</button></section></div>`)}
function scanner(){layout(`${contextBanner()}<div class="grid two"><section class="card"><h3>Crop image review</h3><p class="muted">Upload a photo to discuss visible symptoms with an agronomist. This prototype deliberately does not claim a verified disease diagnosis.</p><label class="label" for="scannerInput">Choose a crop image (up to 5 MB)</label><input id="scannerInput" type="file" accept="image/*" class="input"/><div id="scanPreview" style="margin-top:15px">${state.scannerFile?`<p><b>Image selected:</b> ${escapeHTML(state.scannerFile.name)}</p>`:'<div class="empty">No photo selected yet.</div>'}</div><div class="row"><button id="scannerClear" class="btn secondary">Clear image</button><button id="scanAnalyze" class="btn">Review with AI (if enabled)</button><button class="btn secondary" data-page="advisor">Ask advisor</button></div></section><section class="card"><h3>What to check</h3><div class="list-line">1. Which crop and variety?</div><div class="list-line">2. When did symptoms begin?</div><div class="list-line">3. Are leaves spotted, curled, yellow or damaged?</div><div class="list-line">4. Are nearby plants affected?</div><p class="muted">Symptoms can be caused by pests, pathogens, weather or nutrient issues; a photo alone cannot reliably distinguish all causes. No treatment chemicals or definitive diagnosis are generated.</p></section></div>`);const inp=$('#scannerInput');if(inp)inp.onchange=()=>{const f=inp.files?.[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>5e6){alert('Choose an image below 5MB.');return}state.scannerFile=f;const u=URL.createObjectURL(f);$('#scanPreview').innerHTML='<img alt="Uploaded crop" style="width:100%;max-height:270px;object-fit:contain;border-radius:12px" src="'+u+'" />';};}
function help(){layout(`<div class="grid two"><section class="card"><h3>Account and access</h3><p class="muted">Google login and password reset use real Supabase Auth when configured. Your Google password is never collected by this app.</p><button class="btn" data-page="profile">Open sign-in settings</button><button class="btn secondary" id="resetPassword" style="margin-left:8px">Request password reset</button><h3>Security checklist</h3><div class="list-line">✓ Use an authorized OAuth redirect domain</div><div class="list-line">✓ No secret keys in browser code</div><div class="list-line">✓ Restrict community data using RLS</div><div class="list-line">✓ Share district or sector rather than exact address</div></section><section class="card"><h3>Help center</h3><details open><summary><b>My Google sign-in isn't working</b></summary><p class="muted">Check Supabase Google provider, Site URL, and allowed redirect URLs. Browser popup or account restrictions may apply.</p></details><hr/><details><summary><b>Why don't I see live market prices?</b></summary><p class="muted">Only trusted sources with permission and a documented API can be integrated. Sample offers are never described as verified market prices.</p></details><hr/><details><summary><b>Can the crop scanner diagnose disease?</b></summary><p class="muted">Not yet. Submit observations and consult a trained agronomist to confirm symptoms.</p></details><hr/><details><summary><b>Is NASA climate history a forecast?</b></summary><p class="muted">No. The POWER daily service gives gridded historical meteorological estimates.</p></details></section></div>`)}
function about(){layout(`<div class="hero"><div><span class="eyebrow" style="color:white">BUILT IN RWANDA · FOR RWANDA</span><h2>Ikoranabuhanga rifasha abahinzi. 🇷🇼</h2><p>Better harvests, together. We connect local experience with open Earth observations to make informed crop-rotation choices accessible.</p><button class="btn white" data-page="community">Join the farming circle</button></div><div class="hero-art">🇷🇼</div></div><div class="grid two" style="margin-top:17px"><div class="card"><h3>Our mission</h3><p>Support Rwandan farmers with understandable climate history, local crop planning, community discussion and explainable recommendations.</p><p class="muted">Prototype for NASA Space Apps Field Shift. Not an official NASA product, emergency warning system, or professional agricultural diagnosis service.</p></div><div class="card"><h3>Team and credits</h3><p>Co-founder and developer profiles will be displayed after their names and roles have been confirmed by the team.</p><p class="muted">Sources: NASA POWER, NASA Harvest, local farmers' shared observations with consent, and expert-reviewed agricultural reference material as it becomes available.</p></div></div>`)}
function startSpeech(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){alert('Voice recognition is not available in this browser. Try Chrome or type your question.');return}const r=new Speech();r.lang=state.lang==='rw'?'rw-RW':'en-US';r.interimResults=false;r.onresult=e=>{const box=document.querySelector('#chatQuestion');if(box)box.value=e.results[0][0].transcript};r.onerror=e=>alert('Microphone recognition: '+e.error);r.start()}
async function askNvidia(question){if(!state.supabase||!state.auth)return 'Educational guidance (not live AI): '+answerQuestion(question)+' Sign in to request server AI when configured.';try{const {data:{session}}=await state.supabase.auth.getSession();const res=await fetch('/api/advisor',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.access_token}`},body:JSON.stringify({question,location:state.profile.district,sector:state.profile.sector,crops:state.profile.crops})});const d=await res.json();if(!res.ok)throw Error(d.error||'Advisor unavailable');return d.answer}catch(e){return 'Educational guidance (live AI unavailable): '+answerQuestion(question)+' Check your account or ask an administrator to configure the AI service.'}}
async function initSupabase(){const url=import.meta.env?.VITE_SUPABASE_URL||'https://rrsubgyvjpiedbhlfwza.supabase.co';const key=import.meta.env?.VITE_SUPABASE_ANON_KEY||'sb_publishable_OTvRpm3ZrgYh6_yEh370DQ_JSGySQ4d';if(!url||!key)return false;try{const {createClient}=await import('@supabase/supabase-js');const client=createClient(url,key);state.supabase=client;state.authReady=true;const {data:{session},error}=await client.auth.getSession();if(error)throw error;state.auth=session?.user||null;if(state.auth){await fetchSupaProfile();await fetchSupaPosts();await loadPersonalData();await loadFarmData();await loadMarketListings();await loadMarketInquiries();}await loadStories();setupRealtime();client.auth.onAuthStateChange(async(_event,session)=>{state.auth=session?.user||null;if(state.auth){await fetchSupaProfile();await fetchSupaPosts();await loadPersonalData();await loadFarmData();await loadMarketListings();await loadMarketInquiries()}else{state.accountData=null;state.notifications=[];state.restriction=null;state.farms=[];state.seasons=[];state.savedRotations=[];state.marketCloud=[];state.marketInquiries=[]}setupRealtime();await loadStories();render()});render();return true}catch(e){state.authError='Supabase initialization failed: '+e.message;render();return false}}
async function fetchSupaPosts(){const {data,error}=await state.supabase.from('community_posts').select('id,author_name,district,sector,topic,body,created_at').order('created_at',{ascending:false}).limit(50);if(error){state.authError='Community sync: '+error.message;return}const remote=data.map(p=>({id:'supa-'+p.id,remoteId:p.id,name:p.author_name,district:p.district,sector:p.sector,topic:p.topic,body:p.body,date:new Date(p.created_at).toLocaleDateString(),likes:0,comments:[]}));if(remote.length){const {data:comments, error:commentError}=await state.supabase.from('community_comments').select('post_id,author_name,body').in('post_id',remote.map(p=>p.remoteId)).limit(300);if(!commentError&&comments){for(const post of remote)post.comments=comments.filter(c=>c.post_id===post.remoteId).map(c=>({name:c.author_name,body:c.body}));}}state.posts=[...remote,...storage.get('posts',seedPosts).filter(p=>!p.remoteId)];}

async function fetchSupaProfile(){const {data,error}=await state.supabase.from('farmer_profiles').select('display_name,district,sector,crops,priority').eq('user_id',state.auth.id).maybeSingle();if(error){state.authError='Profile sync: '+error.message;return}if(data){state.profile={...state.profile,name:data.display_name,district:data.district,sector:data.sector,crops:data.crops,priority:data.priority};storage.set('profile',state.profile)}}

async function analyzeCropImage(){if(!state.scannerFile){alert('Choose a photo first.');return}const out=$('#scanPreview');if(!state.supabase||!state.auth){out.insertAdjacentHTML('beforeend','<p class="notice warn">Live vision analysis requires a signed-in Supabase account and configured NVIDIA vision model. No diagnosis was generated.</p>');return}if(state.scannerFile.size>2e6){alert('For AI review choose a photo below 2 MB.');return}try{const dataUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(state.scannerFile)});const {data:{session}}=await state.supabase.auth.getSession();out.insertAdjacentHTML('beforeend','<p class="notice">Analyzing image…</p>');const r=await fetch('/api/crop-scan',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session.access_token}`},body:JSON.stringify({image:dataUrl,crop:state.profile.crops})});const d=await r.json();if(!r.ok)throw Error(d.error);out.insertAdjacentHTML('beforeend','<p class="notice">'+escapeHTML(d.answer)+'</p>')}catch(e){out.insertAdjacentHTML('beforeend','<p class="notice warn">AI review unavailable: '+escapeHTML(e.message)+'</p>')}}

async function fetchMarketNews(){const el=$('#marketNews');if(!el)return;el.textContent='Loading public news…';try{const r=await fetch('/api/market-news');const d=await r.json();if(!r.ok)throw Error(d.error);if(!d.items?.length)throw Error('No articles available');el.innerHTML=d.items.map(x=>`<div class="list-line"><a href="${escapeHTML(x.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(x.title)} ↗</a><div class="muted">${escapeHTML(x.date)} · Source: Google News RSS search · Not produce-price data</div></div>`).join('')}catch(e){el.textContent='News unavailable: '+e.message+' (not a market price feed).'}}


// Farmer testimony requires real submission and human review. Never fabricate success claims.
const storyStatuses = new Set(['pending','published','verified','rejected']);
const storyExcerpt=v=>escapeHTML(String(v||'').slice(0,600));
function mediaPreview(story){
 const media=[];
 if(story.before_signed_url)media.push(`<figure><img loading="lazy" class="story-media" alt="Farmer photo of original conditions" src="${escapeHTML(story.before_signed_url)}"/><figcaption>Starting point (farmer provided)</figcaption></figure>`);
 if(story.after_signed_url)media.push(`<figure><img loading="lazy" class="story-media" alt="Farmer photo of progress" src="${escapeHTML(story.after_signed_url)}"/><figcaption>Progress (farmer provided)</figcaption></figure>`);
 if(media.length)media.unshift('<div class="story-gallery">');
 if(media.length)media.push('</div>');
 if(story.media_signed_url&&story.media_kind==='video')media.push(`<video controls preload="metadata" class="story-media" aria-label="Farmer progress video" src="${escapeHTML(story.media_signed_url)}"></video>`);
 else if(story.media_signed_url&&story.media_kind==='image')media.push(`<img loading="lazy" class="story-media" alt="Farmer-shared crop progress" src="${escapeHTML(story.media_signed_url)}"/>`);
 return media.join('')||'<div class="story-placeholder">🌾<small>No media uploaded</small></div>';
}
function storyCard(story){
 const claimed=story.review_status==='verified'?'Evidence reviewed by team':story.review_status==='published'?'Published farmer account':'Awaiting review';
 const contact=(story.contact_consent&&story.contact_value&&story.contact_type!=='none')?`<div class="story-contact">Optional public contact: ${escapeHTML(story.contact_value)}</div>`:'';
 return `<article class="card farmer-story">${mediaPreview(story)}<div class="story-copy"><div class="row"><span class="chip">${escapeHTML(story.district)}, ${escapeHTML(story.sector)}</span><span class="chip">${escapeHTML(claimed)}</span></div><h3>${escapeHTML(story.title)}</h3><p class="muted">Shared by ${escapeHTML(story.author_display||'Farmer')} · ${escapeHTML(new Date(story.created_at).toLocaleDateString())}</p><b>Where we started</b><p>${storyExcerpt(story.starting_point)}</p><b>What we tried and observed</b><p>${storyExcerpt(story.progress)}</p><b>Changes reported</b><p>${storyExcerpt(story.results)}</p>${contact}<p class="muted">Farmer-reported experience; results vary by farm and season. Publication is not a scientific endorsement.</p></div></article>`;
}
function storyForm(){return `<section class="card"><h3>Share your farming journey</h3><p class="muted">Tell others what you started with, what you changed and what you actually observed. You may upload your own photos or videos (up to 25 MB). Your story stays private until an admin reviews it. Only submit media you own and have permission to publish.</p>${state.supabase&&state.auth?`<form id="storyForm" class="story-form"><div class="field"><label class="label" for="storyTitle">Story title</label><input class="input" id="storyTitle" name="title" minlength="8" maxlength="100" required placeholder="How we changed our maize rotation"/></div><div class="field"><label class="label">Our starting conditions</label><textarea class="input" name="starting_point" required minlength="20" maxlength="2000" placeholder="Which crops, challenges, and growing season?"></textarea></div><div class="field"><label class="label">What we tried (with dates or seasons)</label><textarea class="input" name="progress" required minlength="20" maxlength="2000" placeholder="Describe changes, setbacks and progress"></textarea></div><div class="field"><label class="label">Results we actually observed</label><textarea class="input" name="results" required minlength="20" maxlength="2000" placeholder="Mention any evidence and limits; no guarantees"></textarea></div><div class="field"><label class="label">Photo: starting conditions (optional)</label><input class="input" type="file" accept="image/png,image/jpeg,image/webp" name="before_photo"/></div><div class="field"><label class="label">Photo: progress (optional)</label><input class="input" type="file" accept="image/png,image/jpeg,image/webp" name="after_photo"/></div><div class="field"><label class="label">Video: tell your farming journey (optional)</label><input class="input" type="file" accept="image/png,image/jpeg,image/webp,video/mp4,video/webm,video/quicktime" name="media"/><div class="row" style="margin-top:10px"><button class="btn secondary" type="button" id="storyRecordStart">🎥 Record a short story</button><button class="btn secondary" type="button" id="storyRecordStop" ${state.storyRecorder?'':'disabled'}>Stop recording</button></div><p id="storyRecordStatus" role="status" class="muted">${state.storyRecordedFile?'Recorded video ready: '+escapeHTML(state.storyRecordedFile.name):'Or select an existing video/photo from your device. Camera access requires HTTPS and permission.'}</p></div><div class="field"><label class="label">Contact preference</label><select class="input" name="contact_type"><option value="none">Keep my contacts private</option><option value="email">Show my email</option><option value="phone">Show my phone</option></select></div><div class="field"><label class="label">Contact to publish (optional)</label><input class="input" name="contact_value" maxlength="120" placeholder="Only visible if you opt in above"/></div><label class="check-label"><input type="checkbox" name="consent" required/> I own or have permission to share this content, consent to its publication after review, and understand that contact details I opt to show become public.</label><button class="btn" type="submit" ${state.storyUploadBusy?'disabled':''}>${state.storyUploadBusy?'Submitting…':'Submit for review'}</button></form>`:'<div class="notice warn">Sign in with a configured Supabase Google account to submit a story. Demo data cannot be published as proof. <button class="textbtn" data-page="profile">Go to sign in →</button></div>'}<p id="storyFeedback" role="status" class="muted">${escapeHTML(state.storyError||'')}</p></section>`}
function stories(){layout(`<div class="hero"><div><span class="eyebrow" style="color:#fff">LOCAL VOICES · REAL PROGRESS</span><h2>Trust grows from honest stories.</h2><p>Explore farmer-reported starting points, progress photos and videos, challenges, and outcomes. A reviewed submission is not a guarantee of results.</p><button class="btn white" id="submitStoryOpen">Share your journey ↗</button></div><div class="hero-art">🌱</div></div><div class="grid two" style="margin-top:18px;grid-template-columns:minmax(0,1fr) minmax(280px,380px);align-items:start"><section><h3>Farmer experiences</h3><p class="muted">Published stories from participating farmers, not simulated testimonials. “Evidence reviewed” only appears after a team reviewer checks supporting material.</p>${state.storyLoading?'<div class="card">Loading stories…</div>':state.stories.length?`<div class="story-list">${state.stories.map(storyCard).join('')}</div>`:'<div class="card empty"><h3>No reviewed farmer stories yet</h3><p>Once farmers submit genuine progress evidence and an administrator reviews it, their stories will appear here. We will not invent testimonials.</p></div>'}</section>${storyForm()}</div>`)}
function storyReviewAdmin(){if(!state.storyAdmin){state.page='stories';stories();return}const pending=state.adminStories||[];layout(`<div class="card"><h3>Story review workspace</h3><p>Admin role is controlled by database permissions, not a button or browser setting. Check written consent, misleading claims, identity, media rights, and whether evidence supports the story. Publishing does not mean independent verification.</p><p class="notice warn">Status “Verified evidence” must only be used after a human checks supporting evidence, not solely based on an uploaded video.</p></div><div class="story-list" style="margin-top:16px">${pending.length?pending.map(st=>`<article class="card">${mediaPreview(st)}<h3>${escapeHTML(st.title)}</h3><div class="chip">${escapeHTML(st.review_status)}</div><p>${escapeHTML(st.starting_point)}</p><p>${escapeHTML(st.progress)}</p><p>${escapeHTML(st.results)}</p><p class="muted">By ${escapeHTML(st.author_display)} · ${escapeHTML(st.district)} / ${escapeHTML(st.sector)} · Contact opt-in: ${escapeHTML(String(st.contact_consent))}</p><div class="row story-actions"><button class="btn secondary" data-story-review="${escapeHTML(st.id)}" data-story-status="published">Publish as farmer report</button><button class="btn" data-story-review="${escapeHTML(st.id)}" data-story-status="verified">Mark evidence reviewed</button><button class="btn secondary" data-story-review="${escapeHTML(st.id)}" data-story-status="rejected">Reject</button></div></article>`).join(''):'<div class="card empty">No submitted stories to review.</div>'}</div>`)}
async function enrichStoryMedia(items){return Promise.all(items.map(async st=>{
  const urls={};
  for(const [field,target] of [['media_path','media_signed_url'],['before_media_path','before_signed_url'],['after_media_path','after_signed_url']]){
   if(!st[field])continue;
   try{const {data,error}=await state.supabase.storage.from('farmer-story-media').createSignedUrl(st[field],600);urls[target]=error?null:data.signedUrl}catch{urls[target]=null}
  }
  return {...st,...urls};
}))}
async function loadStories(){if(!state.supabase){state.stories=[];state.storyAdmin=false;return}state.storyLoading=true;try{const client=state.supabase;const {data,error}=await client.from('published_farmer_stories').select('*').in('review_status',['published','verified']).order('created_at',{ascending:false}).limit(30);if(error)throw error;state.stories=await enrichStoryMedia(data||[]);state.storyAdmin=false;state.adminStories=[];if(state.auth){const {data:role,error:roleErr}=await client.from('story_admins').select('user_id').eq('user_id',state.auth.id).maybeSingle();if(roleErr)throw roleErr;state.storyAdmin=!!role;if(state.storyAdmin){const {data:subs,error:subErr}=await client.from('farmer_stories').select('*').order('created_at',{ascending:false}).limit(60);if(subErr)throw subErr;state.adminStories=await enrichStoryMedia(subs||[])}}}catch(e){state.storyError='Stories could not be loaded: '+e.message;state.stories=[];state.storyAdmin=false}finally{state.storyLoading=false}}
async function submitStory(form){const msg=$('#storyFeedback');if(!state.supabase||!state.auth){if(msg)msg.textContent='Sign in with Supabase first.';return}const data=new FormData(form),file=data.get('media'),beforePhoto=data.get('before_photo'),afterPhoto=data.get('after_photo');const media=file instanceof File&&file.size?file:state.storyRecordedFile;const payload={title:String(data.get('title')||'').trim(),starting_point:String(data.get('starting_point')||'').trim(),progress:String(data.get('progress')||'').trim(),results:String(data.get('results')||'').trim(),contact_type:String(data.get('contact_type')||'none'),contact_value:String(data.get('contact_value')||'').trim(),consent:data.get('consent')==='on'};const photoA=beforePhoto instanceof File&&beforePhoto.size?beforePhoto:null,photoB=afterPhoto instanceof File&&afterPhoto.size?afterPhoto:null;const error=validateStoryInput(payload)||validateStoryFile(media)||validateStoryFile(photoA)||validateStoryFile(photoB)||(photoA&&!photoA.type.startsWith('image/')?'Starting photo must be an image.':null)||(photoB&&!photoB.type.startsWith('image/')?'Progress photo must be an image.':null);if(error){if(msg)msg.textContent=error;return}state.storyUploadBusy=true;if(msg)msg.textContent='Saving your story securely…';try{const client=state.supabase;const upload=async file=>{if(!file)return null;const ext=file.type==='video/quicktime'?'mov':file.type.split('/')[1]==='jpeg'?'jpg':file.type.split('/')[1];const path=state.auth.id+'/'+crypto.randomUUID()+'.'+ext;const {error}=await client.storage.from('farmer-story-media').upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return path};const media_path=await upload(media),before_media_path=await upload(photoA),after_media_path=await upload(photoB),media_kind=media?(isSupportedStoryVideo(media.type)?'video':'image'):'none';const row={author_id:state.auth.id,author_display:String(state.profile.name||'Farmer').slice(0,70),district:state.profile.district,sector:state.profile.sector,media_path,media_kind,before_media_path,after_media_path,contact_type:payload.contact_type,contact_value:payload.contact_type==='none'?null:payload.contact_value,contact_consent:payload.contact_type!=='none',title:payload.title,starting_point:payload.starting_point,progress:payload.progress,results:payload.results,consent_at:new Date().toISOString(),review_status:'pending'};const {error:dbError}=await client.from('farmer_stories').insert(row);if(dbError)throw dbError;form.reset();state.storyRecordedFile=null;if(msg)msg.textContent='Your story is submitted for review. It is not public yet.';state.storyError=''}catch(e){if(msg)msg.textContent='Submission failed: '+e.message;}finally{state.storyUploadBusy=false}}
async function reviewStory(id,status){if(!state.storyAdmin||!storyStatuses.has(status)||status==='pending')return;const reason=status==='rejected'?prompt('Briefly state why the submission was rejected (only visible to admins):'):'Reviewed by authorized admin';if(reason===null)return;const {error}=await state.supabase.from('farmer_stories').update({review_status:status,review_note:String(reason).slice(0,500),reviewed_at:new Date().toISOString(),reviewer_id:state.auth.id}).eq('id',id);if(error){alert('Review failed: '+error.message);return}await loadStories();render()}

async function startStoryRecording(){
 const el=$('#storyRecordStatus');
 if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined') {if(el)el.textContent='Recording not supported; upload a video instead.';return}
 try{
  const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:true});
  const mime=['video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t));
  const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);
  const chunks=[];state.storyRecordingStream=stream;state.storyRecorder=recorder;state.storyRecordedFile=null;
  recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
  recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());state.storyRecordingStream=null;state.storyRecorder=null;
   const normalizedType=(recorder.mimeType||'video/webm').split(';')[0];const blob=new Blob(chunks,{type:normalizedType});
   if(blob.size>25*1024*1024){if(el)el.textContent='Recording exceeded 25 MB; please record a shorter clip.';return}
   const extension=blob.type.startsWith('video/mp4')?'mp4':'webm';state.storyRecordedFile=new File([blob],`farmer-progress-${Date.now()}.${extension}`,{type:blob.type});
   if(el)el.textContent='Recording ready to submit ('+Math.round(blob.size/1024)+' KB).';const start=$('#storyRecordStart');if(start)start.disabled=false;const stop=$('#storyRecordStop');if(stop)stop.disabled=true};
  recorder.start();if(el)el.textContent='Recording… Stop when finished. The video is private until reviewed.';
  const start=$('#storyRecordStart');if(start)start.disabled=true;const stop=$('#storyRecordStop');if(stop)stop.disabled=false;
 }catch(e){if(el)el.textContent='Camera permission was denied or unavailable: '+e.message}
}
function stopStoryRecording(){if(state.storyRecorder&&state.storyRecorder.state==='recording')state.storyRecorder.stop()}


// Privacy-first user and administrator tools. All admin permissions are enforced by PostgreSQL RPCs.
function account(){if(!state.supabase||!state.auth){layout(`<section class="card"><h3>Sign in required</h3><p class="muted">Your private farming records are only accessible after a real Supabase Google sign-in. The public demo never creates a pretend account.</p><button class="btn" data-page="profile">Open secure sign-in</button></section>`);return}
 const acts=state.accountData?.activity||[];
 layout(`<div class="grid two"><section class="card"><h3>Protected account</h3><p><b>${escapeHTML(state.auth.email||'Signed-in farmer')}</b></p><p>Farmer name: ${escapeHTML(state.profile.name)}</p><p>Location: ${escapeHTML(state.profile.sector)}, ${escapeHTML(state.profile.district)}</p><p>Crops: ${escapeHTML(state.profile.crops)}</p><p class="muted">Only your own farm profile, activity, and notifications are accessible through database row-level security.</p>${state.restriction?.restricted?'<p class="notice warn">Account is currently restricted from posting. Contact an administrator for review.</p>':''}<button class="btn" data-page="profile">Edit my farm settings</button><button class="btn secondary" id="logout" style="margin-left:8px">Sign out</button></section><section class="card"><h3>Recent account activity</h3>${acts.length?acts.map(a=>`<div class="list-line"><b>${escapeHTML(a.summary)}</b><p class="muted">${escapeHTML(new Date(a.created_at).toLocaleString())}</p></div>`).join(''):'<p class="muted">No recorded activity. Updates appear after your first saved action.</p>'}<button class="textbtn" data-page="notifications">View my notifications →</button></section></div>`)
}
function notifications(){if(!state.supabase||!state.auth){layout('<section class="card">Sign in to see private notifications.</section>');return}
 const items=state.notifications||[];layout(`<section class="card"><div class="row"><h3>Private notifications</h3><button class="btn secondary small" id="markAllRead">Mark all read</button></div>${items.length?items.map(n=>`<div class="list-line"><b>${n.is_read?'':'● '}${escapeHTML(n.title)}</b><p>${escapeHTML(n.body)}</p><small>${escapeHTML(new Date(n.created_at).toLocaleString())}</small></div>`).join(''):'<p class="muted">No notifications yet. This is not an emergency warning system.</p>'}</section>`)
}
function admin(){if(!state.storyAdmin){state.page='stories';stories();return}
 const users=state.adminUsers||[];
 const count=users.length?`<p class="muted">${users.length} registered user records returned (up to 250). Changes are enforced by a database-side administrator role check.</p>`:'<p class="muted">No account records loaded. Run admin_and_activity.sql and reload after signing in as an assigned administrator.</p>';
 const markup=`<section class="card" style="margin-bottom:18px"><h3>Administrator control center</h3><p>Review users, permissions, participation, and account restrictions. No privileged service key is exposed in the browser.</p>${count}<div class="table-wrap" style="overflow-x:auto"><table style="width:100%;text-align:left;border-spacing:10px"><thead><tr><th>Account</th><th>Location</th><th>Posts</th><th>Permission</th><th>Action</th></tr></thead><tbody>${users.map(u=>`<tr><td>${escapeHTML(u.email||'—')}<br><small>${escapeHTML(u.display_name||'No profile')} · ${escapeHTML(new Date(u.joined_at).toLocaleDateString())}</small></td><td>${escapeHTML(u.district||'—')}, ${escapeHTML(u.sector||'—')}</td><td>${Number(u.posts)||0}</td><td>${u.is_admin?'Administrator':u.is_restricted?'Restricted':'Farmer'}</td><td>${u.is_admin?'<small>Admin role managed in secure SQL console</small>':`<button class="btn secondary small" data-restrict-user="${escapeHTML(u.user_id)}" data-restrict-value="${u.is_restricted?'false':'true'}">${u.is_restricted?'Restore posting':'Restrict posting'}</button>`}</td></tr>`).join('')}</tbody></table></div><h3>Content management</h3><p class="muted">Remove inappropriate community records. Actions are performed by protected administrator RPCs.</p>${(state.posts||[]).filter(p=>p.remoteId).slice(0,15).map(p=>`<div class="list-line"><b>${escapeHTML(p.name)}</b> · ${escapeHTML(p.topic)}<p>${escapeHTML(p.body.slice(0,160))}</p><button class="btn secondary small" data-remove-post="${escapeHTML(p.remoteId)}">Delete post</button></div>`).join('')||'<p class="muted">No cloud posts available for moderation.</p>'}</section>`;
 storyReviewAdmin();document.querySelector('.main')?.insertAdjacentHTML('afterbegin',markup);
}
async function recordActivity(type,summary){if(!state.supabase||!state.auth)return;try{await state.supabase.from('farm_activity').insert({user_id:state.auth.id,event_type:type,summary})}catch(e){console.warn('Activity tracking unavailable',e)}}
async function loadPersonalData(){if(!state.supabase||!state.auth)return;try{
 const [activity,notice,restriction]=await Promise.all([
 state.supabase.from('farm_activity').select('event_type,summary,created_at').order('created_at',{ascending:false}).limit(25),
 state.supabase.from('farm_notifications').select('id,title,body,is_read,created_at').order('created_at',{ascending:false}).limit(30),
 state.supabase.from('user_restrictions').select('restricted,reason').eq('user_id',state.auth.id).maybeSingle()]);
 state.accountData={activity:activity.data||[]};state.notifications=notice.data||[];state.restriction=restriction.data||null;
 if(activity.error||notice.error)state.authError='Account activity requires the admin_and_activity.sql migration.';
 if(state.page==='account'||state.page==='notifications')render()
 }catch(e){console.warn('Private account fetch failed',e)}}
async function loadAdminUsers(){if(!state.supabase||!state.auth||!state.storyAdmin)return;const {data,error}=await state.supabase.rpc('admin_user_overview');if(error){state.authError='Admin account records require the secure database migration: '+error.message;render();return}state.adminUsers=data||[];if(state.page==='admin')render()}
async function restrictAccount(userId,restricted){if(!state.storyAdmin||!state.auth||!state.supabase)return;const reason=restricted?prompt('Why are you restricting this account? (Admin-only note)'):'';if(reason===null)return;const {error}=await state.supabase.rpc('admin_set_restriction',{target_user:userId,should_restrict:restricted,explanation:reason||''});if(error){alert('Admin action rejected by database: '+error.message);return}await loadAdminUsers()}
async function removeCommunityPost(id){if(!state.storyAdmin||!state.auth||!state.supabase)return;if(!confirm('Permanently delete this community post and replies?'))return;const {error}=await state.supabase.rpc('admin_remove_community_post',{target_post:id});if(error){alert('Delete rejected: '+error.message);return}await fetchSupaPosts();await loadAdminUsers()}
async function markNotificationsRead(){if(!state.auth||!state.supabase)return;const ids=(state.notifications||[]).filter(n=>!n.is_read).map(n=>n.id);if(!ids.length)return;const {error}=await state.supabase.from('farm_notifications').update({is_read:true}).in('id',ids);if(error){alert('Could not mark notifications: '+error.message);return}await loadPersonalData()}
let realtimeChannel=null;
function setupRealtime(){if(!state.supabase)return;if(realtimeChannel){state.supabase.removeChannel(realtimeChannel);realtimeChannel=null}if(!state.auth)return;
 realtimeChannel=state.supabase.channel('fieldshift-live-'+state.auth.id)
 .on('postgres_changes',{event:'*',schema:'public',table:'community_posts'},async()=>{await fetchSupaPosts();if(state.page==='community'||state.page==='dashboard'||state.page==='admin')render()})
 .on('postgres_changes',{event:'*',schema:'public',table:'community_comments'},async()=>{await fetchSupaPosts();if(state.page==='community'||state.page==='dashboard')render()})
 .on('postgres_changes',{event:'INSERT',schema:'public',table:'nova_chat_messages',filter:'recipient_id=eq.'+state.auth.id},async()=>{if(state.page==='messages')await loadNovaMessages()})
 .on('postgres_changes',{event:'INSERT',schema:'public',table:'farm_notifications',filter:'user_id=eq.'+state.auth.id},async()=>{await loadPersonalData();if(state.page==='notifications')render()}).subscribe();
}


// NOVA CHAT — authenticated, opt-in private farmer messaging.
const novaChat = {owner:null, ready:false, loading:false, busy:false, available:false, users:[], blocks:[], peer:null, messages:[], error:'', notice:''};
function novaReset(){novaChat.owner=state.auth?.id||null;novaChat.ready=false;novaChat.loading=false;novaChat.available=false;novaChat.users=[];novaChat.blocks=[];novaChat.peer=null;novaChat.messages=[];novaChat.error='';novaChat.notice='';}
const novaSafeId=id=>/^[0-9a-f-]{36}$/i.test(String(id||''));
async function novaLoadDirectory(){
 if(!state.auth||!state.supabase)return;
 if(novaChat.loading)return;
 novaChat.loading=true;
 try{
  const [own,peers,blocked]=await Promise.all([
   state.supabase.from('nova_chat_profiles').select('user_id,available').eq('user_id',state.auth.id).maybeSingle(),
   state.supabase.from('nova_chat_profiles').select('user_id,display_name,district').eq('available',true).order('display_name').limit(100),
   state.supabase.from('nova_chat_blocks').select('blocked_id').eq('blocker_id',state.auth.id)
  ]);
  if(own.error||peers.error||blocked.error)throw Error(own.error?.message||peers.error?.message||blocked.error?.message);
  novaChat.available=!!own.data?.available;
  novaChat.blocks=(blocked.data||[]).map(b=>b.blocked_id);
  novaChat.users=(peers.data||[]).filter(u=>u.user_id!==state.auth.id);
  novaChat.ready=true;novaChat.error='';
 }catch(e){novaChat.error=e.message||'Could not load chats';}
 finally{novaChat.loading=false;if(state.page==='messages')novaChatPage();}
}
async function loadNovaMessages(){
 if(!state.auth||!state.supabase||!novaSafeId(novaChat.peer))return;
 const me=state.auth.id,them=novaChat.peer;
 const {data,error}=await state.supabase.from('nova_chat_messages')
  .select('id,sender_id,recipient_id,body,created_at')
  .or(`and(sender_id.eq.${me},recipient_id.eq.${them}),and(sender_id.eq.${them},recipient_id.eq.${me})`)
  .order('created_at',{ascending:false}).limit(100);
 if(error)novaChat.error=error.message;
 else {novaChat.messages=(data||[]).reverse();novaChat.error='';}
 if(state.page==='messages')novaChatPage();
}
function novaChatPage(){
 const me=state.auth?.id||null;
 if(novaChat.owner!==me)novaReset();
 if(!state.auth||!state.supabase){
  layout('<section class="card"><h3>Nova Chat</h3><p>Sign in with Google to message farmers privately.</p><button class="btn" data-page="profile">Sign in to continue</button></section>');return;
 }
 if(!novaChat.ready&&!novaChat.loading&&!novaChat.error)void novaLoadDirectory();
 const selected=novaChat.users.find(u=>u.user_id===novaChat.peer);
 const contacts=novaChat.users.filter(u=>!novaChat.blocks.includes(u.user_id));
 layout(`<section class="nova-chat-shell">
  <div class="nova-chat-head"><div><h2>✉ Nova Chat</h2><p>Private conversations between farmers who choose to be available. No precise locations are shared.</p></div>
  <button type="button" class="btn ${novaChat.available?'secondary':''}" id="novaToggle">${novaChat.available?'Pause my availability':'Join farmer chat'}</button></div>
  ${novaChat.error?`<p class="notice warn" role="alert">${escapeHTML(novaChat.error)}</p>`:''}
  ${novaChat.notice?`<p class="nova-chat-notice" role="status">${escapeHTML(novaChat.notice)}</p>`:''}
  <div class="nova-chat-grid"><aside class="nova-chat-people"><div class="nova-chat-section">Available farmers <span>${contacts.length}</span></div>
  ${!novaChat.available?'<p class="nova-chat-empty">Select “Join farmer chat” to appear in the directory and send messages.</p>':''}
  ${contacts.map(u=>`<button type="button" class="nova-chat-person ${u.user_id===novaChat.peer?'selected':''}" data-nova-peer="${escapeHTML(u.user_id)}"><span class="nova-chat-avatar">${escapeHTML(u.display_name?.charAt(0)||'F')}</span><span><strong>${escapeHTML(u.display_name)}</strong><small>${escapeHTML(u.district||'Farmer')}</small></span></button>`).join('')||'<p class="nova-chat-empty">No other farmers available yet. Invite another registered farmer to join Nova Chat.</p>'}
  </aside><section class="nova-chat-conversation">${selected?`
   <div class="nova-chat-partner"><div><strong>${escapeHTML(selected.display_name)}</strong><small>${escapeHTML(selected.district||'Farmer')} · Private conversation</small></div><button type="button" class="btn secondary small" id="novaBlock">Block farmer</button></div>
   <div class="nova-chat-thread" role="log" aria-label="Conversation">${novaChat.messages.map(m=>`<div class="nova-chat-bubble ${m.sender_id===state.auth.id?'mine':'theirs'}"><p>${escapeHTML(m.body)}</p><small>${escapeHTML(new Date(m.created_at).toLocaleString())}</small></div>`).join('')||'<p class="nova-chat-empty">No messages yet. Start with a respectful greeting.</p>'}</div>
   <form id="novaMessageForm" class="nova-chat-compose"><label for="novaMessage" class="sr-only">Write a private message</label><textarea id="novaMessage" name="message" required maxlength="1500" rows="2" placeholder="Write a message..." ${!novaChat.available?'disabled':''}></textarea><button class="btn" type="submit" ${!novaChat.available?'disabled':''}>Send</button></form>
  `:'<div class="nova-chat-placeholder"><span>🌱</span><h3>Grow connections, one conversation at a time.</h3><p>Select an available farmer to start a private chat.</p></div>'}</section></div>
  <p class="nova-chat-privacy">Please avoid sharing passwords, precise home or farm locations, or sensitive personal information. You can block a farmer at any time.</p>
 </section>`);
 const thread=document.querySelector('.nova-chat-thread');if(thread)thread.scrollTop=thread.scrollHeight;
}
async function novaToggleAvailability(){
 if(!state.auth||!state.supabase||novaChat.busy)return;
 novaChat.busy=true;novaChat.error='';
 try{
  const available=!novaChat.available;
  const profileName=String(state.profile?.name||state.auth.user_metadata?.full_name||'Farmer').trim().slice(0,60)||'Farmer';
  const {error}=await state.supabase.from('nova_chat_profiles').upsert({user_id:state.auth.id,display_name:profileName,district:String(state.profile?.district||'').slice(0,80),available,updated_at:new Date().toISOString()},{onConflict:'user_id'});
  if(error)throw error;
  novaChat.available=available;novaChat.notice=available?'You are now visible to other available farmers.':'Your profile is hidden from the farmer directory.';
  await novaLoadDirectory();
 }catch(e){novaChat.error=e.message||'Could not change availability';}
 finally{novaChat.busy=false;if(state.page==='messages')novaChatPage();}
}
async function novaSend(message){
 if(!novaChat.available||!novaSafeId(novaChat.peer)||novaChat.busy||!state.auth)return;
 const body=String(message||'').trim();if(!body||body.length>1500)return;
 novaChat.busy=true;
 try{
  const {error}=await state.supabase.from('nova_chat_messages').insert({sender_id:state.auth.id,recipient_id:novaChat.peer,body});
  if(error)throw error;
  await loadNovaMessages();
 }catch(e){novaChat.error=e.message||'Message could not be sent';}
 finally{novaChat.busy=false;if(state.page==='messages')novaChatPage();}
}
async function novaBlockSelected(){
 if(!novaSafeId(novaChat.peer)||!state.auth||!confirm('Block this farmer? They will not be able to message you.'))return;
 const {error}=await state.supabase.from('nova_chat_blocks').insert({blocker_id:state.auth.id,blocked_id:novaChat.peer});
 if(error){novaChat.error=error.message;novaChatPage();return;}
 novaChat.peer=null;novaChat.messages=[];novaChat.notice='Farmer blocked.';await novaLoadDirectory();
}
document.addEventListener('click',async e=>{
 if(e.target.closest('#novaToggle')){await novaToggleAvailability();return;}
 if(e.target.closest('#novaBlock')){await novaBlockSelected();return;}
 const button=e.target.closest('[data-nova-peer]');if(!button)return;
 if(!novaChat.available){novaChat.notice='Join farmer chat before opening a conversation.';novaChatPage();return;}
 const id=button.dataset.novaPeer;
 if(!novaSafeId(id)||novaChat.blocks.includes(id))return;
 novaChat.peer=id;novaChat.messages=[];novaChatPage();await loadNovaMessages();
});
document.addEventListener('submit',async e=>{
 if(e.target.id!=='novaMessageForm')return;
 e.preventDefault();const field=e.target.querySelector('[name="message"]');if(field)await novaSend(field.value);
});

